def is_isomorphic(source, target):
    forward, backward = {}, {}
    for left, right in zip(source, target):
        if forward.get(left, right) != right:
            return False
        if backward.get(right, left) != left:
            return False
        forward[left] = right
        backward[right] = left
    return True

def longest_consecutive(nums):
    values = set(nums)
    best = 0
    for start in values:
        if start - 1 in values:
            continue
        length = 1
        while start + length in values:
            length += 1
        best = max(best, length)
    return best

from functools import cmp_to_key

def compare(a, b):
    if a + b > b + a:
        return -1
    if a + b < b + a:
        return 1
    return 0

def largest_number(nums):
    values = sorted(map(str, nums), key=cmp_to_key(compare))
    return ''.join(values).lstrip('0') or '0'

def merge(intervals):
    intervals.sort(key=lambda interval: interval[0])
    merged = []
    for start, end in intervals:
        if not merged or start > merged[-1][1]:
            merged.append([start, end])
        else:
            merged[-1][1] = max(merged[-1][1], end)
    return merged

def subarray_sum(nums, target):
    count = 0
    prefix = 0
    frequency = {0: 1}
    for value in nums:
        prefix += value
        count += frequency.get(prefix - target, 0)
        frequency[prefix] = frequency.get(prefix, 0) + 1
    return count

def pair_sum(values, target):
    left, right = 0, len(values) - 1
    while left < right:
        total = values[left] + values[right]
        if total == target:
            return left, right
        if total < target:
            left += 1
        else:
            right -= 1
    return -1, -1

def is_valid(text):
    pairs = {')': '(', ']': '[', '}': '{'}
    stack = []
    for char in text:
        if char not in pairs:
            stack.append(char)
        elif not stack or stack.pop() != pairs[char]:
            return False
    return not stack

