def daily_temperatures(values):
    answer = [0] * len(values)
    stack = []
    for index, value in enumerate(values):
        while stack and values[stack[-1]] < value:
            previous = stack.pop()
            answer[previous] = index - previous
        stack.append(index)
    return answer

